//! {{ PROJECT_NAME }} — foundation_platform Tauri app.
//!
//! Generated by `cargo platform generate -t PlatformApp -p {{ PROJECT_NAME }}`.
//! Boots a PlatformSession, registers routes, and runs via PlatformBuilder.

use foundation_platform::*;
use tauri::Manager;

fn main() {
    PlatformBuilder::new()
        .register_ewe_protocol()
        .setup(|app| {
            let session = PlatformSession::new();

            // Register your routes here
            session.route("/app/*", webview_app().with_profile(Profile::App));
            session.route("/remote/*", remote_fetch()
                .with_profile(Profile::TrustedRemote)
                .with_cache_policy(CachePolicy::NetworkFirst));

            println!("{{ PROJECT_NAME }} booted — session: {:?}", session.session_id());
            app.manage(session);
            Ok(())
        })
        .build(tauri::generate_context!())
        .expect("failed to build {{ PROJECT_NAME }}")
        .run(|_handle, event| {
            if let tauri::RunEvent::Exit = event {
                println!("{{ PROJECT_NAME }} shutting down.");
            }
        });
}
